commands.command:
# Task registered:
Get-WinEvent -FilterHashtable @{LogName='Microsoft-Windows-TaskScheduler/Operational'; Id=106} -MaxEvents 20 | Select TimeCreated,@{N='Task';E={$_.Message}}
# Task deleted:
Get-WinEvent -FilterHashtable @{LogName='Microsoft-Windows-TaskScheduler/Operational'; Id=141} -MaxEvents 20 | Select TimeCreated,@{N='Task';E={$_.Message}}
# Task action started:
Get-WinEvent -FilterHashtable @{LogName='Microsoft-Windows-TaskScheduler/Operational'; Id=200} -MaxEvents 20 | Select TimeCreated,Message

Get-WinEvent -ComputerName $DC -FilterHashtable @{
    LogName = 'Security'
    Id      = 5136
} | Where-Object {
    $_.Message -match 'msDS-AllowedToActOnBehalfOfOtherIdentity'
} | Select-Object TimeCreated,
    @{N='Actor';E={$_.Properties[3].Value}},
    @{N='Target';E={$_.Properties[8].Value}},
    @{N='Operation';E={$_.Properties[10].Value}} | Format-Table -AutoSize

Get-WinEvent -ComputerName $CA -FilterHashtable @{
    LogName = 'Security'
    Id      = 4887
    StartTime = (Get-Date).AddHours(-24)
} | ForEach-Object {
    [PSCustomObject]@{
        Time         = $_.TimeCreated
        Requester    = $_.Properties[1].Value
        Template     = $_.Properties[4].Value
        RequestedBy  = $_.Properties[3].Value
    }
} | Where-Object { $_.Template -in @('DomainController','SmartcardLogon','SubCA') } | Format-Table -AutoSize

# Run on DNS server
Get-DnsServerZone | Where-Object { -not $_.IsReverseLookupZone -and $_.ZoneType -eq 'Primary' } | ForEach-Object {
    Get-DnsServerResourceRecord -ZoneName $_.ZoneName | Where-Object { $_.HostName -eq '*' }
} | Select-Object ZoneName, HostName, RecordType, RecordData

Get-WinEvent -ComputerName $CA -FilterHashtable @{
    LogName   = 'Security'
    Id        = 4624
    StartTime = (Get-Date).AddHours(-1)
} | Where-Object {
    $_.Message -match 'NTLM' -and $_.Message -notmatch (hostname)
} | Select-Object TimeCreated,
    @{N='User';E={$_.Properties[5].Value}},
    @{N='IP';  E={$_.Properties[18].Value}},
    @{N='AuthPkg';E={$_.Properties[10].Value}} | Format-Table -AutoSize

# Connect: Connect-ExchangeOnline
Get-Mailbox -ResultSize Unlimited | ForEach-Object {
    Get-InboxRule -Mailbox $_.Identity
} | Where-Object {
    $_.ForwardTo -or $_.ForwardAsAttachmentTo -or $_.RedirectTo -or $_.DeleteMessage
} | Select-Object Name, MailboxOwnerID, ForwardTo, ForwardAsAttachmentTo, DeleteMessage | Format-Table -AutoSize

# Requires Microsoft.Graph module
Get-MgOauth2PermissionGrant | Where-Object {
    $_.Scope -match 'Mail.ReadWrite|Mail.Send|MailboxSettings.ReadWrite|Files.ReadWrite.All'
} | ForEach-Object {
    [PSCustomObject]@{
        AppId       = $_.ClientId
        Permission  = $_.Scope
        PrincipalId = $_.PrincipalId
    }
}

Get-MgUser -All | ForEach-Object {
    Get-MgUserSignInActivity -UserId $_.Id -ErrorAction SilentlyContinue
} | Where-Object {
    $_.LastSignInDateTime -gt (Get-Date).AddDays(-1)
} | Select-Object UserDisplayName, LastSignInRequestId, LastSignInDateTime | Format-Table -AutoSize
